function softmax(arr){
  if(!arr||!arr.length) return [];
  var mx=Math.max.apply(null,arr), sum=0, e=arr.map(function(x){ var v=Math.exp(x-mx); sum+=v; return v; });
  return e.map(function(x){ return x/sum; });
}
function topK(arr,k){ var idx=arr.map(function(v,i){return {v:v,i:i};}).sort(function(a,b){return b.v-a.v;}); return idx.slice(0,k).map(function(o){return o.i;}); }
function topP(arr,p,rng){
  rng=rng||Math.random; var probs=softmax(arr); var idx=probs.map(function(v,i){return {v:v,i:i};}).sort(function(a,b){return b.v-a.v;});
  var cum=0, pool=[], pick=null;
  for(var j=0;j<idx.length;j++){ cum+=idx[j].v; pool.push(idx[j].i); if(cum>=p){ pick=pool[Math.floor(rng()*pool.length)]; break; } }
  return pick;
}
var EXPORTS={softmax:softmax,topK:topK,topP:topP};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SoftmaxForgePure = EXPORTS; }
